"""Python half of the Python <-> Go compatibility suite (go/internal/compat).

Run with the REAL frozen Python implementation (rgt_vault). Every command
prints one JSON object on stdout; the Go tests compare it with what Go read.

  roundtrip VAULT_DIR MASTER_FILE POLICY_FILE EXPECT_JSON GO_EXPORT OUT_EXPORT
      Python opens a vault that Go wrote / rotated, with a fixed-master
      provider (the 32 raw bytes in MASTER_FILE):
        * verify_audit_chain() BEFORE touching anything,
        * leases every (namespace, name, version) in EXPECT_JSON and reports
          sha256(plaintext) or the exception class,
        * serves the vault through the Python FastAPI app (TestClient):
          list, POST /v1/audit/verify,
        * import_vault(GO_EXPORT) (Go's export_vault equivalent),
        * writes python/written and exports to OUT_EXPORT for Go to import.

  create-keyring VAULT_DIR POLICY_FILE
      Python creates a NEW vault whose master secret is in the real OS
      keyring (service rgt_vault, user master_key), exactly like
      `rgt-vault serve` did: bootstrap, write secrets (versions, unicode,
      a revoked one), rotate the DEK. Prints the expectations for Go.

  open-keyring VAULT_DIR POLICY_FILE EXPECT_JSON
      Python re-opens that vault (after the Go binary modified it) with the
      real keyring provider and reports chain + reads + epoch.

  keyring-probe
      Reports the active Python keyring backend and whether rgt_vault /
      master_key already exists (the Go test refuses to run if it does).

  keyring-cleanup
      Deletes rgt_vault / master_key (end of the keyring test).

  dpapi-seal PATH ENTROPY_HEX|- SECRET_HEX / dpapi-unseal PATH ENTROPY_HEX|- EXPECT_HEX
  macos-seal SERVICE ACCOUNT SECRET_TEXT / macos-unseal SERVICE ACCOUNT EXPECT_TEXT / macos-delete SERVICE ACCOUNT
  tpm-seal OUTDIR SECRET_HEX / tpm-unseal PRIV PUB EXPECT_HEX
      The platform providers of python/providers (Windows DPAPI, macOS
      Keychain, Linux TPM 2.0), for the "Python seals, Go unseals" matrix
      (and the reverse) on the OS that has them. The unseal commands only report
      whether the secret matches the expected one; they never print it.

Key material is throwaway test data generated by the Go test or the CI job.
"""

import hashlib
import json
import os
import sys

from rgt_vault.providers.base import MasterSecretProvider
from rgt_vault.vault import VaultManager


class FileMaster(MasterSecretProvider):
    def __init__(self, path):
        self.path = path

    def get_secret(self):
        with open(self.path, "rb") as f:
            return f.read()


def read_policy(path):
    with open(path) as f:
        return f.read()


def read_all(vm, expect):
    out = []
    for e in expect:
        try:
            with vm.lease_secret(
                e["name"], "ci-bot", e["namespace"], "python-compat", version=e["version"] or None
            ) as buf:
                out.append(hashlib.sha256(bytes(buf)).hexdigest())
        except Exception as exc:  # report the class, compare in Go
            out.append(type(exc).__name__)
    return out


def sha(s):
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


def served(vm, namespaces, tmpdir):
    """Answers of the Python FastAPI server over the same vault."""
    from fastapi.testclient import TestClient

    from rgt_vault.server.app import build_app
    from rgt_vault.server.auth import TokenStore, generate_token

    store = TokenStore(os.path.join(tmpdir, "py.token"))
    token = generate_token()
    store.write(token)
    client = TestClient(build_app(vm, store))
    h = {"Authorization": "Bearer " + token}
    lists = {}
    for ns in namespaces:
        r = client.get("/v1/secrets", params={"namespace": ns, "agent": "ci-bot"}, headers=h)
        lists[ns] = sorted(s["name"] if isinstance(s, dict) else s for s in r.json().get("secrets", []))
    verify = client.post("/v1/audit/verify", headers=h).json()
    return {"lists": lists, "verify": verify}


def roundtrip(vault_dir, master, policy_file, expect_path, go_export, out_export):
    with open(expect_path) as f:
        expect = json.load(f)
    vm = VaultManager(
        db_path=os.path.join(vault_dir, "vault.db"),
        master_provider=FileMaster(master),
        policy_yaml=read_policy(policy_file),
        rate_limit=1_000_000,
    )
    report = {"vault_id": vm.vault_id, "key_epoch": vm.key_epoch}
    report["chain_before"] = vm.verify_audit_chain()
    report["reads"] = read_all(vm, expect)
    namespaces = sorted({e["namespace"] for e in expect})
    report["server"] = served(vm, namespaces, vault_dir)
    with open(go_export, "rb") as f:
        payload = f.read()
    vm.import_vault(payload)
    report["imported"] = True
    report["chain_after_import"] = vm.verify_audit_chain()
    report["reads_after_import"] = read_all(vm, expect)
    vm.set_secret("written", "from-python", namespace="python", agent="system")
    report["chain_final"] = vm.verify_audit_chain()
    with open(out_export, "wb") as f:
        f.write(vm.export_vault())
    print(json.dumps(report))


def keyring_vault(vault_dir, policy_file):
    # The provider `rgt-vault --provider keyring` (the default) builds: the OS
    # keyring entry rgt_vault/master_key, bootstrapped on first use (P0-2:
    # only when no keychain.json exists yet).
    from rgt_vault.keychain import KeyringProvider

    return VaultManager(
        db_path=os.path.join(vault_dir, "vault.db"),
        master_provider=KeyringProvider(),
        policy_yaml=read_policy(policy_file),
        rate_limit=1_000_000,
    )


def create_keyring(vault_dir, policy_file):
    vm = keyring_vault(vault_dir, policy_file)
    vm.set_secret("api", "api-v1", namespace="prod", agent="system", note="first")
    vm.set_secret("api", "api-v2-ünï🔐", namespace="prod", agent="system")
    vm.set_secret("db", "p4ss/w0rd with spaces", namespace="prod", agent="system", require_2fa=False)
    vm.set_secret("old", "gone", namespace="prod", agent="system")
    vm.revoke_secret("prod", "old")
    vm.rotate_dek()
    vm.set_secret("after-rotate", "post", namespace="default", agent="system")
    expect = [
        {"namespace": "prod", "name": "api", "version": 0, "want": sha("api-v2-ünï🔐")},
        {"namespace": "prod", "name": "api", "version": 2, "want": sha("api-v2-ünï🔐")},
        {"namespace": "prod", "name": "db", "version": 0, "want": sha("p4ss/w0rd with spaces")},
        {"namespace": "default", "name": "after-rotate", "version": 0, "want": sha("post")},
    ]
    print(
        json.dumps(
            {
                "vault_id": vm.vault_id,
                "key_epoch": vm.key_epoch,
                "chain": vm.verify_audit_chain(),
                "expect": expect,
            }
        )
    )


def open_keyring(vault_dir, policy_file, expect_path):
    with open(expect_path) as f:
        expect = json.load(f)
    vm = keyring_vault(vault_dir, policy_file)
    report = {"vault_id": vm.vault_id, "key_epoch": vm.key_epoch}
    report["chain_before"] = vm.verify_audit_chain()
    report["reads"] = read_all(vm, expect)
    vm.set_secret("python-again", "py2", namespace="default", agent="system")
    report["chain_final"] = vm.verify_audit_chain()
    print(json.dumps(report))


def _entropy(h):
    return None if h == "-" else bytes.fromhex(h)


def dpapi_seal(path, entropy_hex, secret_hex):
    from rgt_vault.providers.windows_dpapi import seal_master_secret

    seal_master_secret(bytes.fromhex(secret_hex), path, _entropy(entropy_hex))
    print(json.dumps({"sealed": True}))


def dpapi_unseal(path, entropy_hex, expect_hex):
    from rgt_vault.providers.windows_dpapi import WindowsDPAPIProvider

    secret = WindowsDPAPIProvider(path, _entropy(entropy_hex)).get_secret()
    print(json.dumps({"match": bytes(secret) == bytes.fromhex(expect_hex)}))


def macos_seal(service, account, secret_text):
    from rgt_vault.providers.macos_keychain import seal_master_secret

    seal_master_secret(secret_text.encode("utf-8"), service, account, updatable=True)
    print(json.dumps({"sealed": True}))


def macos_unseal(service, account, expect_text):
    from rgt_vault.providers.macos_keychain import MacOSKeychainProvider

    got = bytes(MacOSKeychainProvider(service, account).get_secret())
    print(json.dumps({"match": got == expect_text.encode("utf-8")}))


def macos_delete(service, account):
    import subprocess

    subprocess.run(["security", "delete-generic-password", "-s", service, "-a", account], check=False)
    print(json.dumps({"deleted": True}))


def tpm_seal(outdir, secret_hex):
    from rgt_vault.providers.linux_tpm import seal_master_secret

    priv, pub = seal_master_secret(bytes.fromhex(secret_hex), outdir)
    print(json.dumps({"priv": str(priv), "pub": str(pub)}))


def tpm_unseal(priv, pub, expect_hex):
    from rgt_vault.providers.linux_tpm import LinuxTPMProvider

    got = bytes(LinuxTPMProvider(priv, pub).get_secret())
    print(json.dumps({"match": got == bytes.fromhex(expect_hex)}))


def keyring_probe():
    import keyring

    backend = keyring.get_keyring()
    present = False
    try:
        present = bool(keyring.get_password("rgt_vault", "master_key"))
    except Exception as exc:  # no usable backend
        print(json.dumps({"backend": type(backend).__name__, "error": type(exc).__name__, "present": False}))
        return
    print(json.dumps({"backend": type(backend).__name__, "module": type(backend).__module__, "present": present}))


def keyring_cleanup():
    import keyring

    try:
        keyring.delete_password("rgt_vault", "master_key")
    except keyring.errors.PasswordDeleteError:
        pass  # nothing to delete: the entry was never created
    print(json.dumps({"deleted": True}))


if __name__ == "__main__":
    cmds = {
        "roundtrip": (roundtrip, 6),
        "create-keyring": (create_keyring, 2),
        "open-keyring": (open_keyring, 3),
        "dpapi-seal": (dpapi_seal, 3),
        "dpapi-unseal": (dpapi_unseal, 3),
        "macos-seal": (macos_seal, 3),
        "macos-unseal": (macos_unseal, 3),
        "macos-delete": (macos_delete, 2),
        "tpm-seal": (tpm_seal, 2),
        "tpm-unseal": (tpm_unseal, 3),
        "keyring-probe": (keyring_probe, 0),
        "keyring-cleanup": (keyring_cleanup, 0),
    }
    if len(sys.argv) < 2 or sys.argv[1] not in cmds:
        raise SystemExit("usage: pycompat.py " + "|".join(cmds) + " ...")
    fn, n = cmds[sys.argv[1]]
    if len(sys.argv) != n + 2:
        raise SystemExit(f"{sys.argv[1]} takes {n} arguments")
    fn(*sys.argv[2:])
